            noiseTexture,
            positionBuffer,
            prog,
            raf: 0,
            renderedFrames: 0,
            renderScale: 1,
            rotation: activeRotation,
            scale: activeScale,
            angle,
            softness,
            speed: activeSpeed,
            offsetX: isImageFilter ? 0 : numberDataset(activePreset.offsetX, 0),
