            if (u.u_offsetX) gl.uniform1f(u.u_offsetX, state.offsetX);
            if (u.u_offsetY) gl.uniform1f(u.u_offsetY, state.offsetY);
            if (u.u_worldWidth) gl.uniform1f(u.u_worldWidth, state.worldWidth);
