                if (u.u_softness) gl.uniform1f(u.u_softness, state.softness);
                if (u.u_noiseFrequency) gl.uniform1f(u.u_noiseFrequency, preset.noiseFrequency !== undefined ? preset.noiseFrequency : 0.4);
